INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6601, 'Judges 20:36', 'Judges', 20, 36, '&nbsp;او بنيامينيانو ته پته ولګېده چې هغوئ شکست وخوړو. بنى اِسرائيلو څنګه فتح وموندله د بنى اِسرائيلو اصلى لښکر د بنيامينيانو نه راواپس شوے وو ځکه چې هغوئ په هغه سړو باندې اعتبار کولو چې هغوئ د جبعې نه ګېرچاپېره په پټو ځايونو کښې کښېنولى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6602, 'Judges 20:37', 'Judges', 20, 37, '&nbsp;دا سړى په منډه منډه جبعې ته لاړل، هغوئ په ښار کښې خوارۀ شول او هلته يې هر يو کس ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6603, 'Judges 20:38', 'Judges', 20, 38, '&nbsp;د بنى اِسرائيلو اصلى لښکر او په پټو ځايونو کښې سړو يوه نښه مقرره کړې وه. کله به چې هغوئ د لوګى يوه لويه وريځ وليده چې د ښار نه ختله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6604, 'Judges 20:39', 'Judges', 20, 39, '&nbsp;نو د جنګ د مېدان بنى اِسرائيليان به راوګرځېدل. تر هغه وخت پورې بنيامينيانو هغه دېرش بنى اِسرائيليان وژلى وُو. او هغوئ د خپل ځان سره ووئيل، ”بې‌شکه چې مونږ د مخکښېنى جنګ په شان هغوئ له شکست ورکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6605, 'Judges 20:40', 'Judges', 20, 40, '&nbsp;بيا نښه څرګنده شوه، د ټول ښار نه د لوګى د وريځې ختل شروع شول. چې بنيامينيانو په ځان پسې وروستو وکتل نو حېران شول چې د ټول ښار نه لمبې ختلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6606, 'Judges 20:41', 'Judges', 20, 41, '&nbsp;نو بنى اِسرائيليان راوګرځېدل او بنيامينيان په وارخطايۍ آخته شوى وُو ځکه چې هغوئ ته پته ولګېده چې د هغوئ تباهى رانزدې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6607, 'Judges 20:42', 'Judges', 20, 42, '&nbsp;هغوئ د بنى اِسرائيلو نه په شا لاړل او کولاو مېدان ته يې منډه کړه، خو هغوئ تښتېدے نۀ شول. هغوئ د اصلى لښکر او د هغه سړو په مينځ کښې ونيولے شول کوم چې اوس د ښار نه راوتل او هغوئ تباه شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6608, 'Judges 20:43', 'Judges', 20, 43, '&nbsp;بنى اِسرائيلو دشمنان ګېر کړل او بغېر د رکاوټ نه هغوئ د جبعه نمرخاتۀ طرف ته يو ځائ پورې ورپسې وُو او د تګ په دوران يې هغوئ وژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6609, 'Judges 20:44', 'Judges', 20, 44, '&nbsp;د بنيامينيانو اتلس زره ښۀ فوجيان ووژلے شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6610, 'Judges 20:45', 'Judges', 20, 45, '&nbsp;هغه نور راوګرځېدل او د کولاو مېدان په طرف د رِمون ګټ ته وتښتېدل. د هغوئ نه پينځۀ زره سړى په لاره کښې ووژلے شول. بنى اِسرائيل په هغه نورو پسې جِدوم ته روان وُو او دوه زره يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6611, 'Judges 20:46', 'Judges', 20, 46, '&nbsp;په هغه ورځ باندې ټول پينځويشت زره بنيامينيان ووژلے شول چې ټول تکړه فوجيان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6612, 'Judges 20:47', 'Judges', 20, 47, '&nbsp;خو شپږ سوه سړى صحرا ته وتښتېدل او چې د رِمون ګټ ته ورسېدل نو هلته څلور مياشتې پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6613, 'Judges 20:48', 'Judges', 20, 48, '&nbsp;بنى اِسرائيليان هغه پاتې شوو بنيامينيانو پسې راواپس شول او ټول سړى، ښځې، ماشومان او داسې ځناور يې هم ووژل. هغوئ په هغه علاقه کښې هر يو ښار وسوزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6614, 'Judges 21:1', 'Judges', 21, 1, '&nbsp;کله چې بنى اِسرائيليان په مصفاه کښې راغونډ شوى وُو، نو هغوئ د مالِک خُدائ سره دا پوخ لوظ کړے وو چې، ”زمونږ يو کس به هم يو بنيامينى له خپله لور نۀ ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6615, 'Judges 21:2', 'Judges', 21, 2, '&nbsp;نو اوس د بنى اِسرائيلو خلق بيت‌ايل ته لاړل او هلته تر ماښامه پورې د خُدائ پاک په حضور کښې ناست وُو. هغوئ په چغو چغو او د ډېر فرياد سره ژړا وکړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6616, 'Judges 21:3', 'Judges', 21, 3, '&nbsp;”اے مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، داسې ولې وشول؟ د بنيامين قبيله ولې د بنى اِسرائيلو نه ورکيږى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6617, 'Judges 21:4', 'Judges', 21, 4, '&nbsp;بل سحر وختى خلقو هلته يو قربان‌ګاه جوړه کړه او د سلامتۍ نذرانې او سوزېدونکې نذرانې يې پېش کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6618, 'Judges 21:5', 'Judges', 21, 5, '&nbsp;هغوئ تپوس وکړو، ”د بنى اِسرائيلو د ټولو قبيلو نه داسې يوه قبيله شته چې په مصفاه کښې د مالِک خُدائ په حضور کښې غونډې له نۀ وى تلې؟“ هغوئ پوخ قسم کړے وو چې هر څوک مصفاه له نۀ وى تلے نو هغه به وژلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6619, 'Judges 21:6', 'Judges', 21, 6, '&nbsp;بنى اِسرائيل په خپلو وروڼو بنيامينيانو باندې خفه وُو او وې وئيل، ”نن د بنى اِسرائيلو نه يوه قبيله جدا شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6620, 'Judges 21:7', 'Judges', 21, 7, '&nbsp;مونږ څۀ وکړُو چې د بنيامين کوم سړى پاتې دى چې هغوئ له د ښځو بندوبست وکړُو؟ مونږ د مالِک خُدائ سره پوخ لوظ کړے دے چې مونږ به هغوئ له خپلې لوڼه نۀ ورکوو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6621, 'Judges 21:8', 'Judges', 21, 8, '&nbsp;کله چې هغوئ تپوس وکړو چې د بنى اِسرائيلو په قبيلو کښې کۀ داسې يوه قبيله وى چې هغه په مصفاه کښې غونډې ته نۀ وى تلې، نو هغوئ ته پته ولګېده چې د جِلعاد د يبيس يو کس هم هلته نۀ وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6622, 'Judges 21:9', 'Judges', 21, 9, '&nbsp;کله چې د خلقو حاضرى اخستلے شوه نو د يبيس يو کس هم نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6623, 'Judges 21:10', 'Judges', 21, 10, '&nbsp;نو غونډې خپل دولس زره تکړه سړى د دې حُکم سره ولېږل، ”لاړ شئ او په يبيس کښې سره د ښځو او ماشومانو هر يو کس ووژنئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6624, 'Judges 21:11', 'Judges', 21, 11, '&nbsp;ټول نران ووژنئ او هغه ټولې ښځې هم ووژنئ چې د سړى سره څملاستلې وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6625, 'Judges 21:12', 'Judges', 21, 12, '&nbsp;د يبيس په خلقو کښې هغوئ څلور سوه داسې پېغلې پېدا کړې چې د چا لاس هم ورته نۀ وُو رسېدلے، نو هغوئ يې په سيلا کښې کېمپ ته راوستلې، کوم چې د کنعان په مُلک کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6626, 'Judges 21:13', 'Judges', 21, 13, '&nbsp;بيا ټولې غونډې بنيامينيانو ته دا خبر ولېږلو کوم چې د رِمون ګټ سره وُو او د روغې دپاره جرګه يې ورولېږله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6627, 'Judges 21:14', 'Judges', 21, 14, '&nbsp;بنيامينيان واپس راغلل او نورو بنى اِسرائيلو هغوئ له د يبيس جينکۍ ورکړې کومې چې وژلے شوې نۀ وې خو دا د هغوئ دپاره کافى نۀ وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6628, 'Judges 21:15', 'Judges', 21, 15, '&nbsp;خلق په بنيامينيانو باندې خفه وُو ځکه چې مالِک خُدائ د بنى اِسرائيلو د قبيلو اِتحاد مات کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6629, 'Judges 21:16', 'Judges', 21, 16, '&nbsp;نو د غونډې مشرانو ووئيل، ”د بنيامين په قبيله کښې نورې ښځې نشته، کوم سړى چې پاتې دى نو د هغوئ دپاره د ښځو بندوبست څنګه وکړُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6630, 'Judges 21:17', 'Judges', 21, 17, '&nbsp;داسې دې بېخى ونۀ شى چې د بنى اِسرائيلو د دولسو قبيلو نه يوه ختمه شى. مونږ له داسې څۀ طريقه لټول په کار دى چې د بنيامين قبيله ژوندۍ پاتې شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6631, 'Judges 21:18', 'Judges', 21, 18, '&nbsp;خو مونږ دا اجازت نه شُو ورکولے چې زمونږ لوڼه وادۀ کړى، ځکه چې مونږ په هغه کس باندې لعنت وئيلے دے چې يو بنيامينى له اجازت ورکړى چې زمونږ د لوڼو نه يوه وادۀ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6632, 'Judges 21:19', 'Judges', 21, 19, '&nbsp;بيا هغوئ ووئيل، ”په سيلا کښې د مالِک خُدائ کلنى مېله زر راروانه ده.“ د بيت‌ايل شمال او د لبونه جنوب طرف ته او د بيت‌ايل او شِکم په مينځ کښې چې کومه لار ده او نمرخاتۀ طرف ته سيلا دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6633, 'Judges 21:20', 'Judges', 21, 20, '&nbsp;هغوئ بنيامينيانو ته ووئيل، ”لاړ شئ او د انګورو په باغونو کښې پټ شئ', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6634, 'Judges 21:21', 'Judges', 21, 21, '&nbsp;او وګورئ، کله چې په مېله کښې د سيلا جينکۍ ګډېدو له راوځى نو تاسو د انګورو باغونو نه راوځئ. نو تاسو هر يو کس يوه يوه ښځه د هغوئ نه په زور راونيسئ او د بنيامين علاقې ته يې د ځان سره بوځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6635, 'Judges 21:22', 'Judges', 21, 22, '&nbsp;کۀ د هغوئ پلاران يا وروڼه مونږ له راشى او اِعتراض وکړى، نو مونږ به ورته ووايو چې د هغوئ سره ښېګړه وکړئ او هغوئ دې ستاسو لوڼه د ځان دپاره وساتى، ځکه چې مونږ ته په جنګ کښې د ټولو سړو دپاره ښځې نۀ دى مِلاو شوې. او چې تاسو خپلې لوڼه هغوئ له نۀ دى ورکړې نو په دې وجه تاسو ګناهګار نۀ يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6636, 'Judges 21:23', 'Judges', 21, 23, '&nbsp;بنيامينيانو هم داسې وکړل، د هغوئ هر يو کس د هغه ښځو نه يوه يوه ښځه خوښه کړه کومې چې په سيلا کښې ګډېدې او بو يې تلې. بيا هغوئ واپس خپلې علاقې ته لاړل، خپل ښارونه يې دوباره جوړ کړل او هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6637, 'Judges 21:24', 'Judges', 21, 24, '&nbsp;هم په هغه وخت باقى بنى اِسرائيل روان شول او هر يو واپس خپلې قبيلې، خپل خاندان او خپل جائيداد له لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6638, 'Judges 21:25', 'Judges', 21, 25, '&nbsp;په هغه وخت کښې د بنى اِسرائيلو بادشاه نۀ وو. هر چا هم هغه شان کار کولو چې څنګه يې خوښه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6639, 'Ruth 1:3', 'Ruth', 1, 3, '&nbsp;چې اِلى‌مَلِک مړ شو، نو نعومى د دوو زامنو سره يواځې پاتې شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6640, 'Ruth 1:4', 'Ruth', 1, 4, '&nbsp;نو هغوئ د موآبۍ ښځو عرفه او روت سره ودونه وکړل. تقريباً لس کاله وروستو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6641, 'Ruth 1:5', 'Ruth', 1, 5, '&nbsp;محلون او کِليون هم مړۀ شول، او نعومى بېخى يواځې پاتې شوه، چې نۀ يې خاوند وو او نۀ زامن.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6642, 'Ruth 1:6', 'Ruth', 1, 6, '&nbsp;څۀ وخت وروستو نعومى خبر شوه چې مالِک خُدائ خپلو خلقو ته د فصلونو نعمت ورکړو، هغه د اِنږوريانو سره د موآب نه تللو ته تياره شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6643, 'Ruth 1:7', 'Ruth', 1, 7, '&nbsp;دوئ يو ځائ يهوداه ته واپس روانې شوې، خو په لاره کښې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6644, 'Ruth 1:8', 'Ruth', 1, 8, '&nbsp;نعومى هغوئ ته ووئيل، ”تاسو کور ته واپس لاړې شئ او د خپلو ميندو سره اوسېږئ. مالِک خُدائ دې په تاسو مهربانه وى لکه څنګه چې تاسو په ما او زما په مړو زامنو مهربانه وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6645, 'Ruth 1:9', 'Ruth', 1, 9, '&nbsp;او مالِک خُدائ دې وکړى چې تاسو دواړه بيا وادۀ شئ او خپل کورونه آباد کړئ.“ نو نعومى هغوئ رخصتولو دپاره ښُکلې کړې. خو هغوئ په ژړا شوې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6646, 'Ruth 1:10', 'Ruth', 1, 10, '&nbsp;او هغوئ هغې ته ووئيل، ”نه، مونږ به تا سره ستا مُلک ته ځُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6647, 'Ruth 1:11', 'Ruth', 1, 11, '&nbsp;نعومى په جواب کښې ورته ووئيل، ”زما لوڼو، تاسو واپس لاړې شئ، تاسو ما سره ولې تلل غواړئ؟ په دې خيال چې زما به بيا زامن وشى او هغوئ به تاسو وادۀ کړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6648, 'Ruth 1:12', 'Ruth', 1, 12, '&nbsp;واپس خپلو کورونو ته لاړې شئ، زۀ ډېره بوډۍ او د بيا وادۀ کېدو نۀ يم. کۀ چرې زۀ داسې وګڼم چې تر اوسه څۀ اُميد شته، نو کۀ نن شپه وادۀ هم شوم او زما زامن وشول،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6649, 'Ruth 1:13', 'Ruth', 1, 13, '&nbsp;تاسو به د هغوئ د غټېدو اِنتظار کوئ څۀ؟ دا به تاسو د بل چا سره د ودېدو نه ايساروى څۀ؟ نه، زما لوڼو، تاسو ته پته ده چې دا نۀ شى کېدے. مالِک خُدائ زما مل نۀ دے، په تاسو زما زړۀ سوزى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6650, 'Ruth 1:14', 'Ruth', 1, 14, '&nbsp;دوئ بيا په ژړا شوې. عرفه په مخه ښه وئيلو دپاره خواښې ښُکله کړه او واپس کور ته لاړه، خو روت د هغې لمن نيولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6651, 'Ruth 1:15', 'Ruth', 1, 15, '&nbsp;نو نعومى هغې ته ووئيل، ”اے روت، ستا يور خپلو خلقو او د هغوئ معبودانو له لاړه. هغې پسې واپس کور ته لاړه شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6652, 'Ruth 1:16', 'Ruth', 1, 16, '&nbsp;خو روت ورته ووئيل، ”ما د ځان نه مۀ شړه، ما ته مۀ وايه چې درنه ايساره شم. چې چرته ځې، هلته به ځم، چې چرته اوسې، هلته به اوسم. ستا خلق به زما خلق وى، او ستاسو خُدائ پاک به زما خُدائ پاک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6653, 'Ruth 1:17', 'Ruth', 1, 17, '&nbsp;چې چرته مرې، هلته به مرم، چې چرته ښخېږې هلته به ښخېږم. مالِک خُدائ دې ما ته په قهر شى کۀ د مرګ نه بغېر په بل څۀ ستا نه جدا شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6654, 'Ruth 1:18', 'Ruth', 1, 18, '&nbsp;کله چې نعومى ته پته ولګېده چې روت د تلو کلکه اراده کړې ده، نو هغې نور څۀ ورته ونۀ وئيل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6655, 'Ruth 1:19', 'Ruth', 1, 19, '&nbsp;دوئ مزل کولو چې بيت‌لحم ته ورسېدې. د هغوئ په رسېدو، د ښار ټول خلق د هغوئ په ننداره شول، او ښځو ووئيل، ”دا په رښتيا نعومى ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6656, 'Ruth 1:20', 'Ruth', 1, 20, '&nbsp;هغې ووئيل، ”ما ته نعومى مۀ وايئ، ما ته ماره وايئ، ځکه چې قادر خُدائ زما ژوند تريخ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6657, 'Ruth 1:21', 'Ruth', 1, 21, '&nbsp;زۀ بختوره لاړم، خو مالِک خُدائ تش لاس سپېره راولېږلم. ما ته ولې نعومى وايئ، چې قادر خُدائ زۀ غورزولې يم. او هغۀ په سختۍ کښې اچولې يم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6658, 'Ruth 1:22', 'Ruth', 1, 22, '&nbsp;نو داسې، نعومى د خپلې موآبۍ اِنږور روت سره د موآب نه واپس راغله. د اوربشو لَو شروع وو، چې دوئ بيت‌لحم ته ورسېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6659, 'Ruth 2:1', 'Ruth', 2, 1, '&nbsp;د نعومى يو رشته‌دار وو چې نوم يې بوعز وو، دا يو مالدار او مشر سړے وو، کوم چې د هغې د خاوند اِلى‌مَلِک د خاندان نه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6660, 'Ruth 2:2', 'Ruth', 2, 2, '&nbsp;يوه ورځ روت نعومى ته ووئيل، ”ما پرېږده چې پټو ته لاړه شم چې د لَوګرو نه پاتې شوى وَږى راټول کړم. زما يقين دے چې څوک به مې د ځان سره پرېږدى.“ نعومى ورته ووئيل، ”ځه لورې، لاړه شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6661, 'Ruth 2:3', 'Ruth', 2, 3, '&nbsp;روت پټو ته لاړه او لَوګرو پسې وروستو پاتې شوى وَږى يې راټولول. نو داسې وشول چې هغه د بوعز په پټى کښې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6662, 'Ruth 2:4', 'Ruth', 2, 4, '&nbsp;په دې کښې بوعز په خپله د بيت‌لحم نه راغلو. او لَوګرو ته يې سلام وکړو، او ورته يې ووئيل، ”مالِک خُدائ مو مل شه.“ او هغوئ په جواب کښې ووئيل، ”مالِک خُدائ دې بختور کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6663, 'Ruth 2:5', 'Ruth', 2, 5, '&nbsp;بوعز د لَوګرو مشر نه تپوس وکړو، ”دا ځوانه ښځه څوک ده؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6664, 'Ruth 2:6', 'Ruth', 2, 6, '&nbsp;مشر جواب ورکړو، ”دا ځوانه ښځه د نعومى سره د موآب نه راغلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6665, 'Ruth 2:7', 'Ruth', 2, 7, '&nbsp;هغې ما ته ووئيل چې ما په لَوګرو پسې پاتې شوو وږو راټولولو ته پرېږده. هغه د سحر وختى نه تر اوسه پورې کار کوى او د لږې لحظې دپاره دالان لاندې دمې ته کښېناسته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6666, 'Ruth 2:8', 'Ruth', 2, 8, '&nbsp;بيا بوعز روت ته ووئيل، ”زما خبره واوره، د دې پټى نه بغېر بل ځائ کښې وَږى مۀ ټولوه، دلته د ښځو سره يو ځائ اوسه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6667, 'Ruth 2:9', 'Ruth', 2, 9, '&nbsp;سړو ته ګوره چې چرته هغوئ لو کوى نو په هغوئ پسې شاته ښځو سره کار کوه. ما خپلو سړو ته وئيلى دى چې هغوئ تا نۀ تنګوى. هر کله چې تۀ تږې شې، نو د هغې منګو نه اوبۀ څښه چې دوئ ډک کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6668, 'Ruth 2:10', 'Ruth', 2, 10, '&nbsp;روت د عزت نه پړمخې په زمکه پرېوته، او بوعز ته يې ووئيل، ”زۀ ولې ستاسو په نظر کښې درنه يم؟ تاسو ولې په ما مسافرې دومره مِهربانه يئ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6669, 'Ruth 2:11', 'Ruth', 2, 11, '&nbsp;بوعز ووئيل، ”زۀ د هر څۀ نه خبر يم چې تا د خاوند د مرګ نه پس د خواښې څومره خِدمت کړے دے. ما ته پته ده چې تا څنګه مور پلار او خپل مُلک پرېښودو او هغه خلقو له راغلې چې تا مخکښې نۀ پېژندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6670, 'Ruth 2:12', 'Ruth', 2, 12, '&nbsp;مالِک خُدائ دې تا له د دې بدل درکړى. مالِک خُدائ دې تا له پوره اجر درکړى، کوم چې د بنى اِسرائيلو خُدائ پاک دے، چې ورته د پناه دپاره راغلې يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6671, 'Ruth 2:13', 'Ruth', 2, 13, '&nbsp;روت ورته ووئيل، ”نېکه، تۀ په ما ډېر مِهربانه يې. ستاسو نرمو خبرو زۀ په آرام کړې يم، سره د دې چې زۀ ستاسو د وينځې برابره هم نۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6672, 'Ruth 2:14', 'Ruth', 2, 14, '&nbsp;د خوراک په وخت بوعز روت ته ووئيل، ”روټۍ واخله، او دا سرکې سره وخوره.“ نو هغه د لَوګرو سره کښېناسته، او بوعز څۀ وريتې دانې هم هغې له ورکړې. هغې دومره وخوړه چې پرې ښۀ مړه شوه، او څۀ خوراک پاتې هم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6673, 'Ruth 2:17', 'Ruth', 2, 17, '&nbsp;نو روت تر ماښامه پورې په پټى کښې وَږى راټولول، کله چې هغې دا ټول وټکول، تقريباً اتۀ سېره وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6674, 'Ruth 2:18', 'Ruth', 2, 18, '&nbsp;نو هغې دا ښار ته يوړل او خواښې ته يې وښودل چې هغې څومره راټول کړى دى. او د هغې د خوراک نه پاتې شوې وريتى دانې يې هم هغې له ورکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6675, 'Ruth 2:19', 'Ruth', 2, 19, '&nbsp;نعومى د هغې نه تپوس وکړو، ”تا نن دا دومره وَږى چرته نه راټول کړى دى؟ تا د چا په پټى کښې کار کولو؟ هغه سړے دې بختور شى چې ستا خيال يې وساتلو.“ نو روت نعومى ته ووئيل چې، ”نن ما د چا په پټو کښې کار کولو د هغه سړى نوم بوعز دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6676, 'Ruth 2:20', 'Ruth', 2, 20, '&nbsp;نعومى ووئيل، ”مالِک خُدائ دې بوعز بختور کړى. مالِک خُدائ همېشه د مړو او ژوندو سره وعدې پوره کوى.“ هغې دا هم ووئيل چې، ”هغه سړے زمونږ نزدې رشته‌دار دے، هغه زمونږ د خيال ساتلو ذمه وار دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6677, 'Ruth 2:21', 'Ruth', 2, 21, '&nbsp;بيا روت ووئيل، ”د دې نه ښۀ خبره دا ده، چې هغۀ ما ته ووئيل چې د لَوګرو د کار تر ختمولو پورې وَږى راټولوه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6678, 'Ruth 2:22', 'Ruth', 2, 22, '&nbsp;نعومى روت ته ووئيل، ”آو لورې، دا به ډېره ښۀ وى چې د بوعز په پټو کښې د ښځو سره کار کوې. کۀ چرې تۀ د بل چا پټو ته لاړې نو څوک به لاس درواچوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6679, 'Ruth 2:23', 'Ruth', 2, 23, '&nbsp;نو روت د هغوئ سره کار کولو او وَږى يې راټولول، تر هغې پورې چې ټول غنم او اوربشې ورېبلے شوې. او د خپلې خواښې سره اوسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6680, 'Ruth 3:1', 'Ruth', 3, 1, '&nbsp;څۀ وخت وروستو نعومى روت ته ووئيل، ”زۀ به خامخا ستا دپاره خاوند لټوم، چې ستا خپل کور آباد شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6681, 'Ruth 3:2', 'Ruth', 3, 2, '&nbsp;دا ياد ساته چې بوعز، د چا د ښځو سره چې تا کار کولو، هغه زمونږ رشته‌دار دے. اوس دا خبره واوره، هغه به نن شپه په درمند کښې اوربشې بادوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6682, 'Ruth 3:3', 'Ruth', 3, 3, '&nbsp;نو ولامبه، عطر ولګوه، او د ټولو نه ښې جامې واچوه. او بيا لاندې درمند ته لاړه شه، خو چې هغۀ ته دا پته ونۀ لګى چې تۀ هلته يې تر هغې پورې چې هغۀ خوراک څښاک ختم کړے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6683, 'Ruth 3:4', 'Ruth', 3, 4, '&nbsp;تۀ ورته ګوره چې هغه چرته څملى، چې کله هغه اودۀ شى، نو لاړه شه او د هغۀ نه څادر اوچت کړه او ورسره اوده شه. نو هغه به تا ته ووائى چې تۀ به څۀ کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6684, 'Ruth 3:5', 'Ruth', 3, 5, '&nbsp;روت ووئيل، ”زۀ به هم هغه شان وکړم لکه څنګه چې تا ما ته ووئيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6685, 'Ruth 3:6', 'Ruth', 3, 6, '&nbsp;نو روت درمند ته لاړه او چې څنګه خواښې ورته وئيلى وُو هم هغه شان يې وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6686, 'Ruth 3:7', 'Ruth', 3, 7, '&nbsp;کله چې بوعز خوراک څښاک ختم کړو، نو هغه ښۀ په سور کښې وو. هغه د اوربشو ډېرى له لاړو او څملاستو. روت غلې غلې ورغله، څادر يې ترې اوچت کړو او هغۀ سره اوده شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6687, 'Ruth 3:8', 'Ruth', 3, 8, '&nbsp;هغه د شپې ناڅاپه راويښ شو، په بل مخ واوړېدو، نو حېران شو چې هغۀ سره يوه ښځه اوده ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6688, 'Ruth 3:9', 'Ruth', 3, 9, '&nbsp;هغۀ ترې تپوس وکړو، ”تۀ څوک يې؟“ هغې جواب ورکړو، ”زۀ روت يم، ستا د پښو خاوره، په ما نظر وکړه، ځکه چې تۀ زما نزدې رشته‌داره يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6689, 'Ruth 3:10', 'Ruth', 3, 10, '&nbsp;هغۀ ووئيل، ”مالِک خُدائ دې بختوره کړه. تۀ اوس د هغې نه هم لويه وفادارى ښائې چې تا د خواښې دپاره څۀ کړى وُو. تا کولے شول چې يو ځوان سړے دې خوښ کړے وے، مالدار يا غريب، خو تا داسې ونۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6690, 'Ruth 3:11', 'Ruth', 3, 11, '&nbsp;خو روت، اوس خفه کېږه مه. چې تۀ څنګه غواړې زۀ به هم هغه شان وکړم، لکه چې په ښار کښې ټولو خلقو ته پته ده، چې تۀ يوه شريفه ښځه يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6691, 'Ruth 3:12', 'Ruth', 3, 12, '&nbsp;دا رښتيا دى چې زۀ ستا نزدې رشته‌دار يم او زۀ ستا خيال ساتم، خو دلته ستا، زما نه نزدې بل خپل هم شته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6692, 'Ruth 3:13', 'Ruth', 3, 13, '&nbsp;پاتې شپه دلته تېره کړه، او سحر به مونږ وګورو چې هغه ستا ذمه وارى اخلى يا نه. کۀ اخلى، نو ټيک ده، او کۀ نۀ اخلى، نو زۀ بيا په ژوندى مالِک خُدائ قسم کوم چې زۀ به ستا خيال ساتم. نو اوس دلته تر سحره پورې پاتې شه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6693, 'Ruth 3:14', 'Ruth', 3, 14, '&nbsp;نو هغه ورسره هلته اوده وه او د چرګ د بانګ نه مخکښې پاڅېده چې څوک يې ونۀ وينى، ځکه چې بوعز نۀ غوښتل چې چا ته دا پته ولګى چې د هغې شپه هلته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6694, 'Ruth 3:15', 'Ruth', 3, 15, '&nbsp;بوعز هغې ته ووئيل، ”خپل څادر دلته خور کړه.“ او هغې هغه خور کړو، او هغۀ هغې له تقريباً شپاړس سېره اوربشې په څادر کښې واچولې او هغه پنډ يې ورپه سر کړو. او هغه ښار ته واپس راغله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6695, 'Ruth 3:16', 'Ruth', 3, 16, '&nbsp;کله چې هغه کور ته راغله، خواښې ترېنه تپوس وکړو، ”لورې، څۀ چل وشو؟“ نو روت هغه هر څۀ ورته ووئيل چې بوعز د هغې دپاره کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6696, 'Ruth 3:17', 'Ruth', 3, 17, '&nbsp;روت دا هم ووئيل چې، ”هغۀ ما ته وئيلى وُو چې تۀ خپلې خواښې له خالى لاسونه مۀ ځه، نو هغۀ ما له دومره ډېرې اوربشې راکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6697, 'Ruth 3:18', 'Ruth', 3, 18, '&nbsp;نعومى ورته ووئيل، ”زما لورې اوس صبر کوه چې د دې خبرې څۀ حل راونۀ وځى نو بوعز به تر هغې پورې په قلاره نۀ کښېنى چې نن دا مسئله حل نۀ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6698, 'Ruth 4:1', 'Ruth', 4, 1, '&nbsp;نو بوعز د ښار په دروازه کښې د جرګې ځائ ته لاړو او هلته کښېناستو. بيا د اِلى‌مَلِک نزدې رشته‌دار، چې بوعز د هغۀ په حقله وئيلى وُو، راغلو، نو بوعز ورته آواز وکړو، ”زما ملګريه، دېخوا راشه، او دلته کښېنه.“ هغه ورَغلو او هلته کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6699, 'Ruth 4:2', 'Ruth', 4, 2, '&nbsp;بيا بوعز د ښار لس مشران راغونډ کړل او هغوئ ته يې هم ووئيل چې کښېنئ او هغوئ کښېناستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6700, 'Ruth 4:3', 'Ruth', 4, 3, '&nbsp;هغۀ رشته‌دار ته ووئيل، ”اوس نعومى د موآب نه واپس راغلې ده، هغه زمونږ د رشته‌دار اِلى‌مَلِک پټے خرڅول غواړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');